insert into guides (id,content) values ('brake-pads',$j${"id": "brake-pads", "title": "Brake pads", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "brake-hero", "alsoFits": "2006–09 GTI · 05–10 Jetta 2.0T (312mm front / 286mm rear) · A3 8P 2.0T", "category": "Brakes", "kind": "repair", "variants": {"question": "Front or rear?", "hint": "Different calipers, different tools. Front pistons push back; rear pistons have to be screwed back.", "options": [{"id": "front", "label": "Front pads", "when": "7mm hex guide bolts, 312mm rotor, wear sensor"}, {"id": "rear", "label": "Rear pads", "when": "13mm guide bolts, 286mm rotor, piston screws in"}]}, "glance": {"timeFirst": "1–1.5 hr", "timeRepeat": "40 min", "difficulty": 2, "cost": "$50–150 per axle", "risk": "Car on stands · brake fluid · never touch friction surfaces with greasy hands", "why": "Pads are the part of the brake that's designed to wear away. On the GTI the fronts do most of the work and go first; the rears last longer but bind up more. It's the most common job on any car, and one of the most satisfying to do yourself.", "note": "Vendor and forum times agree: about an hour an axle, longer the first time you meet a seized rotor screw."}, "heroCap": "Caliper (piston side) slides on two guide pins in the carrier. Two small bolts free the caliper; two big ones free the carrier. For pads only, the carrier stays.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Front pads: typically 30,000–50,000 miles", "only": ["front"]}, {"text": "Rear pads: typically 50,000–70,000 miles", "only": ["rear"]}], "earliest": "Much sooner with track use or a sticking caliper slide pin", "detail": "The wear sensor on the front inner pad lights the dash when the pad reaches about 3mm. Rears have no sensor; look through the wheel or pull it. A pad worn to the backing plate scores the rotor and turns a pad job into a rotor job.", "factors": ["Spirited or track driving", "Sticking guide pins (uneven wear)", "City stop-and-go", "A stuck parking brake (rears)"], "inspect": ["Every tire rotation: pad thickness through the wheel spokes"], "confidence": {"level": "community", "n": 4, "note": "Owner reports and vendor notes; no factory mileage exists because it depends on the driver."}}, "should": {"yesIf": ["Pad warning light on the dash (front)", "Less than about 3mm of friction material left", "Squeal at low speed that goes away when you brake harder (wear indicator)", "Grinding: you're already into the rotor"], "codes": [], "notes": ["Pads and rotors: if the rotor has a lip at the edge you can catch a fingernail on, or the pads wore unevenly, do rotors too (that's the next guide). New pads on a worn rotor bed in badly and feel soft.", "Both sides of an axle, always, with the same pad compound."], "confidence": {"level": "high", "n": 4, "note": "Standard practice; consistent across sources."}}, "parts": [{"tier": "oe", "name": "Front pad set, Genuine/OEM (TRW or Textar)", "pn": "1K0 698 151 (confirm by VIN)", "note": "Includes wear sensor on most kits", "price": "$60–90", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Rear pad set, Genuine/OEM", "pn": "1K0 698 451 (confirm by VIN)", "note": "", "price": "$40–70", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Rear caliper guide-pin bolts, M8x22 (×4)", "pn": "self-locking", "note": "Replace every time (ECS, Bentley)", "price": "$6", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Front pad wear sensor", "pn": "if not in the kit", "note": "The old one is usually cut through", "price": "$10", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Brake caliper grease, brake cleaner", "pn": "—", "note": "Silicone or ceramic paste for pad ears and guide pins", "price": "$12", "links": []}], "aftermarket": [{"name": "Ferodo DS2500 / Hawk HPS", "note": "Street-performance compounds: more bite, more dust, fine cold. The forum default for a spirited daily.", "price": "$120–180", "signal": "Spirited-daily pick", "links": []}, {"name": "EBC Redstuff / Yellowstuff", "note": "Red for low dust street; Yellow for track days but noisy on the street.", "price": "$100–160", "signal": "Know which colour you want", "links": []}, {"name": "Akebono Euro ceramic", "note": "Quiet, very low dust, slightly less bite than OE. Popular for a clean-wheels daily.", "price": "$60–90", "signal": "Low-dust pick", "links": []}], "tools": [{"name": "Jack + stands, 17mm for lugs"}, {"name": "7mm hex bit (front caliper guide bolts), flat screwdriver for the spring clip", "only": ["front"]}, {"name": "13mm socket + 15mm wrench (rear caliper bolts), rear piston retractor tool (cube or wind-back kit)", "only": ["rear"]}, {"name": "Large C-clamp or piston spreader (front)", "only": ["front"]}, {"name": "Wire brush, brake cleaner, bungee or wire to hang the caliper, torque wrench to 35 Nm"}], "before": ["Loosen the reservoir cap and remove a little fluid if it's near MAX; pushing pistons back raises the level.", "Never let the caliper hang by its hose.", "Both sides of the axle in one session."], "steps": [{"n": 1, "title": "Wheel off, look", "blocks": [{"t": "text", "b": "Lugs loose on the ground, raise the axle, stands under the body, wheel off. Look at the pad through the caliper window and at the rotor edge for a lip."}]}, {"n": 2, "title": "Free the caliper", "blocks": [{"t": "text", "b": "Pry the big spring clip off the caliper face with a screwdriver. Unplug the wear-sensor wire from its clip. Pull the two rubber caps off the back of the caliper and remove the two 7mm hex guide bolts. Lift the caliper off the carrier and hang it from the spring with a bungee.", "only": ["front"]}, {"t": "text", "b": "Pry the spring clip off. Hold each guide pin with a 15mm wrench and remove the 13mm bolt; discard the bolts. Lift the caliper off and hang it. The parking-brake cable stays connected.", "only": ["rear"]}, {"t": "ill", "id": "brake-hero", "cap": "Guide bolts (small) free the caliper; carrier bolts (large) stay put for a pad job."}]}, {"n": 3, "title": "Old pads out, clean everything", "blocks": [{"t": "text", "b": "Pull the pads out of the carrier (front: the inner pad clips into the piston). Wire-brush the carrier's pad seats until the new pads slide freely in them; a pad that binds here is what causes uneven wear. Check the guide-pin boots and that the pins slide."}]}, {"n": 4, "title": "Retract the piston", "caution": true, "blocks": [{"t": "text", "b": "Put the old inner pad across the piston and squeeze it back with a C-clamp, slowly, watching the reservoir level.", "only": ["front"]}, {"t": "text", "b": "Rear pistons screw in. Use the retractor tool to turn the piston clockwise while pushing; do not just squeeze it or you'll wreck the parking-brake mechanism inside. Stop when it's flush and line up one of the piston's notches with the nub on the new inner pad.", "only": ["rear"]}, {"t": "warn", "b": "Slow. A piston forced back too fast can pop the master-cylinder seals or overflow the reservoir onto the paint."}]}, {"n": 5, "title": "New pads in", "blocks": [{"t": "text", "b": "Thin smear of caliper grease on the pad ears and the back of the pads (never the friction face). Outer pad into the carrier, inner pad clipped into the piston (front) or seated with its nub in the piston notch (rear). New wear sensor clipped into the inner pad and routed the same way as the old one."}]}, {"n": 6, "title": "Caliper back on", "blocks": [{"t": "text", "b": "Lower the caliper over the pads, grease and fit the guide bolts, and torque them. Refit the rubber caps and the spring clip.", "only": ["front", "rear"]}, {"t": "torque", "label": "Front caliper guide bolts (7mm hex)", "nm": 28, "alt": [35], "c": {"level": "varies", "n": 3, "note": "28 Nm (Bentley), 30 and 35 Nm in forum tables for the same caliper. Any of these is fine; they're small bolts, don't overdo them."}, "only": ["front"]}, {"t": "torque", "label": "Rear caliper bolts (M8, new, 13mm)", "nm": 35, "c": {"level": "high", "n": 3, "note": "ECS, Bentley and forum agree: 35 Nm, new self-locking bolts."}, "only": ["rear"]}]}, {"n": 7, "title": "Other side, then pump the pedal", "blocks": [{"t": "text", "b": "Repeat on the other side. Wheels on (120 Nm). Before you drive: pump the brake pedal until it's firm so the pistons take up the gap. Check the reservoir level and cap it."}]}, {"n": 8, "title": "Bed them in", "blocks": [{"t": "text", "b": "A few gentle stops, then five or six firm stops from 40 mph without coming to a complete halt, then a few minutes of driving without braking to cool. Skip this and the pads glaze and squeal for weeks."}]}], "alsoReplace": [{"name": "Rotors", "why": "If there's a lip or scoring, the extra work is two carrier bolts and a set screw. See the rotor guide."}, {"name": "Brake fluid", "why": "If it's dark or over two years old, you already have the wheels off. See the flush guide."}], "check": {"tab": "Read the wear", "title": "Reading the old pads", "illId": "brake-hero", "illCap": "Uneven wear is a caliper problem, not a pad problem.", "rows": [{"see": "Both pads worn evenly, 2–3mm left", "means": "Normal end of life.", "do": "Replace pads."}, {"see": "Inner pad far more worn than outer", "means": "Guide pins sticking or piston sluggish.", "do": "Clean and grease pins; if the piston won't retract smoothly, rebuild or replace the caliper."}, {"see": "Tapered wear across one pad", "means": "Carrier pad seats corroded; pad can't float.", "do": "Wire-brush the carrier seats hard, or replace the carrier."}, {"see": "Pad worn to metal, rotor scored", "means": "Way past due.", "do": "Pads and rotors."}], "c": {"level": "community", "n": 3, "note": "Standard diagnosis; consistent across sources."}}, "aftercare": ["Bed in properly.", "Re-check guide bolt torque after 100 miles if you had to fight the caliper on.", "Squeal after a week: pads not bedded, or the anti-rattle spring is off."], "disagreements": [{"topic": "Front guide-bolt torque", "pos": "28, 30 and 35 Nm across sources for the same caliper.", "call": "28–35. Not a critical value."}, {"topic": "Reuse caliper bolts?", "pos": "Rear bolts are self-locking and every source says replace; front OE pads come with new bolts and thread-locker.", "call": "New on the rear; front, reuse with blue thread-locker if the kit didn't include them."}], "sources": ["ECS Tuning Mk5 GTI rear pads and rotors procedure", "myturbodiesel Mk5 Golf torque thread (Bentley)", "Golfmk7 and Golfmk6 brake torque threads", "Audizine PQ35 rear caliper thread"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('brake-rotors',$j${"id": "brake-rotors", "title": "Brake rotors (and pads)", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "brake-hero", "alsoFits": "2006–09 GTI · 05–10 Jetta 2.0T · A3 8P 2.0T", "category": "Brakes", "kind": "repair", "variants": {"question": "Front or rear?", "hint": "Front rotors are 312mm and the carrier bolts are big and tight. Rear rotors are 286mm and the carrier bolts are stretch bolts you replace.", "options": [{"id": "front", "label": "Front rotors", "when": "Carrier bolts 190–200 Nm, reuse"}, {"id": "rear", "label": "Rear rotors", "when": "Carrier bolts 90 Nm + 90°, replace"}]}, "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2.5, "cost": "$120–300 per axle with pads", "risk": "Very tight carrier bolts · seized set screw · heavy front rotors", "why": "Rotors wear a fraction of a millimetre per pad set and warp if they overheat. When there's a lip at the edge, grooves you can feel, or a shudder under braking, they're done. Always with new pads: a fresh pad on a worn rotor never beds right.", "note": "The set screw is the wildcard. Plan for it to strip and have a drill ready."}, "heroCap": "Carrier off (two big bolts), set screw out, rotor off the hub. Clean the hub face before the new rotor goes on or you'll build in a wobble.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Front rotors: typically every second pad set, 60,000–100,000 miles", "only": ["front"]}, {"text": "Rear rotors: typically 80,000–120,000 miles, often rust-limited rather than wear-limited", "only": ["rear"]}], "earliest": "Sooner if pads were run to metal, or on track cars", "detail": "Minimum thickness is stamped on the rotor hat (MIN TH). Measure with a caliper gauge away from the lip. Salt-belt cars usually lose rear rotors to rust pitting long before they're thin.", "factors": ["Pads run to the backing plate", "Track days", "Road salt (rears especially)", "Sticking caliper"], "inspect": ["Every pad change: thickness against the MIN TH stamp, and run a fingernail across the face"], "confidence": {"level": "community", "n": 4, "note": "Owner practice; the MIN TH stamp is the only hard number."}}, "should": {"yesIf": ["Lip at the rotor edge you can catch a nail on", "Shudder or pulsing pedal under braking", "Grooves or heat spots on the face", "Below the MIN TH stamped on the hat", "Pads wore to metal"], "codes": [], "notes": ["Slotted or drilled? On a street car neither does much beyond looks, and drilled rotors can crack from the holes with track heat. Plain or slotted blanks from a good maker are the value pick."], "confidence": {"level": "high", "n": 4, "note": "Standard practice; consistent."}}, "parts": [{"tier": "oe", "name": "Front rotors, 312mm (pair)", "pn": "1K0 615 301 (confirm by VIN)", "note": "Zimmermann, ATE, Brembo blanks are OE-quality", "price": "$90–160", "links": [], "only": ["front"]}, {"tier": "oe", "name": "Rear rotors, 286mm (pair)", "pn": "1K0 615 601 (confirm by VIN)", "note": "", "price": "$70–120", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Pads for the same axle", "pn": "see the pads guide", "note": "Always with rotors", "price": "$40–150", "links": []}, {"tier": "oe", "name": "Rotor set screws, T30 (×2)", "pn": "N 906 218 01", "note": "You will destroy at least one", "price": "$3", "links": []}, {"tier": "oe", "name": "Rear carrier bolts (×4)", "pn": "M12, torque-to-yield", "note": "Replace (ECS, Bentley, forums)", "price": "$12", "links": [], "only": ["rear"]}, {"tier": "oe", "name": "Rear caliper guide-pin bolts (×4)", "pn": "M8x22 self-locking", "note": "Replace", "price": "$6", "links": [], "only": ["rear"]}], "aftermarket": [{"name": "Zimmermann coated / ATE PremiumOne (pairs with pads)", "note": "OE-spec blanks with an anti-rust coating on the hat and edges. The sensible upgrade.", "price": "$100–180", "signal": "Value pick", "links": []}, {"name": "StopTech / Brembo slotted", "note": "Slots help with pad gassing on track and look the part. Slightly more pad wear.", "price": "$180–300", "signal": "Spirited pick", "links": []}, {"name": "Big brake kit (R32 345mm carriers, or aftermarket BBK)", "note": "A different project: bigger rotors, different carriers, wheel clearance to check. Not this guide.", "price": "$500+", "signal": "Different job", "links": []}], "tools": [{"name": "Jack + stands, 17mm for lugs, breaker bar"}, {"name": "21mm socket for the front carrier bolts (½\" drive, they are very tight); 7mm hex for guide bolts; C-clamp", "only": ["front"]}, {"name": "18mm or 21mm for the rear carrier bolts (check yours); 13mm + 15mm for caliper bolts; rear piston retractor", "only": ["rear"]}, {"name": "T30 Torx and an impact driver for the set screw; drill and bits for when it strips"}, {"name": "Wire brush or Roloc disc for the hub face; torque wrench to 200 Nm; angle gauge (rear)"}], "before": ["Penetrating oil on the set screw and carrier bolts while you get the wheel off.", "Front rotors are heavy; don't drop one on a toe or the carrier's threads.", "Reservoir cap loose, level checked."], "steps": [{"n": 1, "title": "Wheel off, caliper off", "blocks": [{"t": "text", "b": "Follow the pads guide to free the caliper and hang it (spring clip, sensor wire, guide bolts). Pull the old pads."}]}, {"n": 2, "title": "Carrier off", "caution": true, "blocks": [{"t": "text", "b": "Two big bolts behind the hub hold the carrier to the knuckle. Breaker bar, steady pull. Lift the carrier away.", "only": ["front", "rear"]}, {"t": "warn", "b": "Rear carrier bolts are torque-to-yield: they stretch once and are done. Throw them away and fit new ones on reassembly, or they can back out.", "only": ["rear"]}, {"t": "warn", "b": "Front carrier bolts are torqued to 190–200 Nm and can be rusted in. Keep the breaker bar in line and your knuckles clear when it lets go.", "only": ["front"]}]}, {"n": 3, "title": "Set screw and rotor", "timeSink": true, "blocks": [{"t": "text", "b": "T30 impact driver on the set screw: a few sharp hits, then turn. If it rounds, drill the head off; the rotor comes off and the stub unscrews with pliers. Then the rotor: a few whacks with a hammer on the hat between the studs, or a bolt threaded into the hub's puller hole, breaks the rust bond."}, {"t": "ill", "id": "brake-hero", "cap": "Set screw is only there to hold the rotor while the wheel is off. Snug, never tight."}]}, {"n": 4, "title": "Clean the hub face", "blocks": [{"t": "text", "b": "Wire brush or Roloc disc the hub face back to bare metal, especially the raised ring the rotor sits on. Any rust flake left behind is runout you'll feel as a shudder in a month. Wipe the new rotor's face with brake cleaner to remove the shipping oil."}]}, {"n": 5, "title": "New rotor and carrier", "blocks": [{"t": "text", "b": "Rotor on, set screw in snug (about 4 Nm; just enough to hold it). Carrier over the rotor, bolts in.", "only": ["front", "rear"]}, {"t": "torque", "label": "Front carrier bolts (×2, reuse)", "nm": 190, "alt": [200], "c": {"level": "varies", "n": 3, "note": "190 Nm (Bentley) vs 200 Nm (forum tables). Either; it's a big bolt and both are in range."}, "only": ["front"]}, {"t": "torque", "label": "Rear carrier bolts (×2, NEW)", "nm": 90, "c": {"level": "high", "n": 3, "note": "90 Nm then a further 90° turn, new bolts every time. ECS, Bentley and forums agree."}, "note": "+90° turn", "only": ["rear"]}]}, {"n": 6, "title": "Pads and caliper", "blocks": [{"t": "text", "b": "Continue with the pads guide from 'Retract the piston': new pads, caliper on, guide bolts torqued, clip and sensor back."}]}, {"n": 7, "title": "Other side, pump, bed in", "blocks": [{"t": "text", "b": "Repeat. Wheels on at 120 Nm. Pump the pedal firm before moving. Bed in: several firm stops from 40 mph, then cool. New rotors and pads need this more than pads alone."}]}], "alsoReplace": [{"name": "Wheel bearing check", "why": "Hub is exposed. Spin it and feel for roughness; a grumble now is a bearing job later."}, {"name": "Brake fluid flush", "why": "Wheels are off; see the flush guide."}, {"name": "Rear caliper parking-brake return spring", "why": "If the lever is sluggish, the caliper is on its way to sticking.", "only": ["rear"]}], "check": {"tab": "Read the rotor", "title": "Reading the old rotor", "illId": "brake-hero", "illCap": "A lip means wear; blue spots mean heat; rust ring means the pad isn't contacting.", "rows": [{"see": "Even wear, small lip, above MIN TH", "means": "Serviceable.", "do": "Could reuse with new pads, but bedding is worse. Most replace."}, {"see": "Grooves, blue heat spots, shudder", "means": "Overheated or run with worn pads.", "do": "Replace. Check caliper function."}, {"see": "Heavy rust pitting on the outer inch (rears)", "means": "Pad isn't sweeping the whole face; typical salt-belt rear.", "do": "Replace rotor and pads; check the caliper slides."}], "c": {"level": "community", "n": 3, "note": "Standard diagnosis."}}, "aftercare": ["Bed in.", "Shudder after new rotors: hub face wasn't clean, or lug bolts were tightened in a star pattern by impact. Re-torque by hand.", "Re-check carrier bolts after 100 miles."], "disagreements": [{"topic": "Front carrier torque", "pos": "190 vs 200 Nm.", "call": "190–200."}, {"topic": "Drilled rotors", "pos": "Look good; some forum voices swear by them.", "call": "Slotted or plain for anything that sees heat."}], "sources": ["ECS Tuning Mk5 GTI rear pads and rotors procedure", "myturbodiesel Bentley torque thread", "Golfmk7 / Golfmk6 torque threads", "Audizine PQ35 caliper thread"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('brake-flush',$j${"id": "brake-flush", "title": "Brake fluid flush", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "bleed-order", "alsoFits": "All Mk5 platform cars (Golf, Jetta, A3, Eos): same order", "category": "Brakes", "kind": "repair", "variants": {"question": "Manual or DSG?", "hint": "Manual cars share the brake reservoir with the clutch slave cylinder, which gets bled first.", "options": [{"id": "manual", "label": "6-speed manual", "when": "Clutch slave bled first"}, {"id": "dsg", "label": "DSG", "when": "Brakes only"}]}, "glance": {"timeFirst": "1 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$25–40 (fluid) + a $50 pressure bleeder once", "risk": "Fluid eats paint · don't let the reservoir run dry", "why": "Brake fluid absorbs water from the air through the hoses. Wet fluid boils at a lower temperature (soft pedal after hard stops) and corrodes the ABS unit and calipers from the inside. VW says change it every two years; almost nobody does.", "note": "An hour with a pressure bleeder. Double that with a helper on the pedal."}, "heroCap": "VW's order is front-left, front-right, rear-left, rear-right, because of how the ABS unit is plumbed. Clutch slave first on a manual.", "lifespan": {"title": "When to expect it", "headline": ["Factory: first change at 3 years, then every 2 years, regardless of miles"], "earliest": null, "detail": "Time, not distance. Fluid that's dark amber or brown in the reservoir is overdue. A cheap test strip or moisture tester tells you the water content; above 3% is time.", "factors": ["Humid climate", "Track days (boil it once and it's done)", "Unknown history"], "inspect": ["Look at the reservoir colour at every oil change"], "confidence": {"level": "medium", "n": 3, "note": "Factory schedule via a vendor summary; owner practice agrees."}}, "should": {"yesIf": ["Over two years since the last flush, or unknown", "Fluid is dark", "Pedal goes soft after repeated hard stops", "You just did calipers, lines, or a clutch"], "codes": [], "notes": ["DOT 4 only, from a sealed bottle. An opened bottle on the shelf has been absorbing water for months. Buy small bottles.", "If the reservoir runs dry during the job, air enters the ABS unit and a scan tool (VCDS) is needed to cycle it out. Keep it topped."], "confidence": {"level": "high", "n": 4, "note": "Method and rationale consistent across the manual, two owner write-ups and vendor guidance."}}, "parts": [{"tier": "oe", "name": "DOT 4 brake fluid, 1.5 L", "pn": "VW 501 14 spec (ATE TYP200, Pentosin, Motul DOT 4)", "note": "Sealed bottles", "price": "$25–40", "links": []}, {"tier": "oe", "name": "Bleeder nipple dust caps", "pn": "if missing", "note": "", "price": "$4", "links": []}], "aftermarket": [{"name": "ATE TYP200 / Motul RBF600", "note": "Higher dry and wet boiling points for track use. RBF600 needs more frequent changes; TYP200 is the sensible middle.", "price": "$20–35 / L", "signal": "Track-day pick", "links": []}], "tools": [{"name": "Pressure bleeder (Motive or similar) with the VW/Audi 45mm cap", "note": "Turns a two-person job into one"}, {"name": "11mm wrench (flare nut or ratcheting), clear hose, catch bottle"}, {"name": "Turkey baster, rags, spray bottle of water for drips"}], "before": ["Cover the paint around the reservoir and behind each wheel.", "Pump the bleeder to 10–15 psi, not 30; higher isn't needed and stresses the master-cylinder seals.", "Wheels off makes the rear nipples much easier, but it can be done through the spokes."], "steps": [{"n": 1, "title": "Wheels off (recommended)", "blocks": [{"t": "text", "b": "Raise the car on four stands, wheels off, or do it one axle at a time. Find the bleeder nipple on each caliper (top, inboard) and pop the dust cap."}]}, {"n": 90, "title": "Set up the pressure bleeder", "blocks": [{"t": "text", "b": "Turkey-baster the old fluid out of the reservoir down to the minimum line and refill with fresh DOT 4 from a sealed bottle. Screw the bleeder cap onto the reservoir and pump it to 10–15 psi. Keep the reservoir topped the whole time; if it runs dry the ABS unit takes in air and only a scan tool can bleed it."}, {"t": "warn", "b": "Brake fluid strips paint in minutes. Cover the fender and wing, keep a spray bottle of water handy, and wipe drips immediately."}]}, {"n": 91, "title": "Bleed in the manual's order", "caution": true, "blocks": [{"t": "text", "b": "Manual car first: 11mm on the clutch slave bleeder (on the bell housing), let 50 ml run, close, pump the clutch pedal 10–15 times, open again for another 50 ml, close.", "only": ["manual"]}, {"t": "text", "b": "The brakes: front-left, front-right, rear-left, rear-right. Yes, front first; the ABS unit's layout makes the usual furthest-first rule wrong on this car. At each caliper: dust cap off, 11mm wrench on the nipple, hose into a catch bottle, open until the fluid runs clear and bubble-free, close, cap."}, {"t": "ill", "id": "bleed-order", "cap": "The order VW specifies. Clutch slave first on a manual."}, {"t": "note", "b": "Finishing touch owners swear by: after the pressure bleed, have a helper do five firm pedal strokes per caliper (open the nipple with the pedal down, close before it comes up) to chase any last air."}]}, {"n": 92, "title": "Close up and test", "blocks": [{"t": "text", "b": "Release bleeder pressure, remove the cap, set the reservoir level between the marks (not above MAX; the pads will wear and the level will rise as they're changed). Pedal should be firm within the first inch. Drive gently around the block, brake progressively harder, and check every bleeder for weeping."}]}], "alsoReplace": [{"name": "Clutch slave bleed", "why": "On a manual it shares the reservoir; it's already first in the order.", "only": ["manual"]}, {"name": "Rear brake hose check", "why": "Look for cracks or bulges in the rubber hoses while you're at each corner. See the stainless-line guide if they're tired."}], "check": {"tab": "Read the fluid", "title": "What came out?", "illId": "bleed-order", "illCap": "Colour tells the story.", "rows": [{"see": "Pale yellow, clear", "means": "Recent. Someone loved this car.", "do": "Note the date; next in two years."}, {"see": "Amber to brown", "means": "Years old, wet.", "do": "Flush until clear at every corner. Expect more than a litre."}, {"see": "Black flecks or sludge", "means": "Seals breaking down or a caliper cooking the fluid.", "do": "Flush, then inspect that caliper for drag; rebuild if it's hot after a drive."}], "c": {"level": "community", "n": 3, "note": "Standard practice."}}, "aftercare": ["Write the date on a bit of tape on the reservoir.", "Firm pedal after the first drive: done. Soft pedal: bleed again in the same order; if still soft, the ABS unit has air and needs a scan-tool bleed."], "disagreements": [{"topic": "Bleed order", "pos": "VW manual: FL, FR, RL, RR. Pelican and general practice: RR, LR, RF, LF.", "call": "The manual. The ABS unit's layout is the reason, and VW says 'proper bleeding cannot be ensured' otherwise."}, {"topic": "Bleeder pressure", "pos": "10 psi vs 2 bar (30 psi).", "call": "10–15 psi."}], "sources": ["VWVortex threads quoting the Mk5 repair manual bleed sequence", "MicksGarage Project GTI bleeding write-up", "Pelican Parts Mk5 GTI bleeding article", "DAP Mk5 service schedule", "Passat B6 (same platform) bleed procedure"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('brake-lines-ss',$j${"id": "brake-lines-ss", "title": "Stainless brake lines", "fits": "2006 VW GTI · 2.0T FSI (BPY)", "heroId": "bleed-order", "alsoFits": "All Mk5 platform cars", "category": "Brakes", "kind": "upgrade", "glance": {"timeFirst": "2 hr", "timeRepeat": "1 hr", "difficulty": 2.5, "cost": "$100–180 for four", "risk": "Fluid on paint · line routing · full bleed required", "why": "The rubber hoses at each wheel swell a little every time you press the pedal. Braided stainless lines don't, so the pedal feels firmer and more consistent, especially when the fluid's hot. It's the same job as replacing tired rubber hoses, just with a better part.", "note": "Two hours including the flush that has to follow. The lines themselves are ten minutes a corner."}, "heroCap": "Each corner has one flexible hose from the hard line on the body to the caliper. Swap the hose, then bleed in VW's order.", "lifespan": {"title": "When owners do this", "headline": ["Usually with a pad/rotor upgrade or when a rubber hose shows cracks, often past 100,000 miles"], "earliest": null, "detail": "Rubber hoses don't have a factory replacement interval but they age: surface cracks, bulging under pressure, or a hose that's soft to squeeze means it's overdue. Owners fit stainless at that point because the price gap is small.", "factors": ["Track days", "Rubber hoses cracked or bulging", "Doing a brake flush anyway"], "inspect": ["Every fluid flush: squeeze and look at each hose"], "confidence": {"level": "community", "n": 3, "note": "Forum consensus; no factory interval."}}, "should": {"yesIf": ["Pedal feels soft or inconsistent when hot", "Rubber hoses are cracked, bulging, or original at 100k+", "You're flushing the fluid anyway", "You want the last bit of pedal feel from a pad upgrade"], "codes": [], "notes": ["Buy DOT-compliant lines from a real brand with a PTFE core and a protective outer sleeve. The cheap unbranded sets are the one place in this app where 'aftermarket' can mean 'worse than stock'."], "confidence": {"level": "medium", "n": 3, "note": "Rationale and method consistent; no factory torque for the fittings was found this pass."}}, "parts": [{"tier": "aftermarket", "name": "Stainless brake line set (4)", "pn": "see options below", "note": "Front and rear, with new banjo bolts and copper washers if the kit includes them", "price": "$100–180", "links": []}, {"tier": "oe", "name": "DOT 4 fluid, 1.5 L", "pn": "—", "note": "Full flush follows", "price": "$25–40", "links": []}, {"tier": "oe", "name": "Copper crush washers for banjo fittings", "pn": "if not in kit", "note": "Never reuse", "price": "$5", "links": []}], "aftermarket": [{"name": "StopTech / Goodridge G-Stop", "note": "DOT-compliant, PTFE core, colour sleeve, all clips and washers. The two names the forums trust.", "price": "$120–180", "signal": "Forum favorite", "links": []}, {"name": "ECS / USP stainless kits", "note": "Same construction, often bundled with a fluid flush kit.", "price": "$100–150", "signal": "Value pick", "links": []}], "tools": [{"name": "11mm flare-nut wrench (hard-line unions) and 14mm/17mm for banjo bolts; 11mm for bleeders"}, {"name": "Pressure bleeder, hose, catch bottle, turkey baster"}, {"name": "Line clamp or a bag over the reservoir to slow the drip while a line is off; rags; water spray"}], "before": ["Flare-nut wrench only on the hard-line unions; an open-end wrench rounds them and then you're replacing hard lines.", "One corner at a time, and cap or plug the open hard line to slow the drip.", "Everything gets bled afterwards, in VW's order."], "steps": [{"n": 1, "title": "Wheels off, find the hose", "blocks": [{"t": "text", "b": "Four stands, wheels off. At each corner: a rubber hose from a bracket on the body/strut (hard-line union, 11mm flare nut) to the caliper (banjo bolt or threaded fitting)."}]}, {"n": 2, "title": "Slow the flow", "blocks": [{"t": "text", "b": "Suck the reservoir down near MIN and put a plastic bag under the cap to seal it; the system will barely drip with a line open. Don't clamp the old rubber hose with pliers if you plan to keep it; you don't, so a hose clamp is fine."}]}, {"n": 3, "title": "Swap the line", "caution": true, "blocks": [{"t": "text", "b": "Flare-nut wrench on the hard-line union, back it off, pull the retaining clip and free the hose from the bracket. At the caliper, remove the banjo bolt (or unscrew the fitting). Fit the new line the same way round, new copper washers either side of the banjo, thread the hard-line union by hand first, then snug. Clip the line into the bracket."}, {"t": "warn", "b": "Route the new line exactly where the old one ran and turn the steering lock to lock (front) and bounce the suspension to confirm it can't touch the wheel, spring or strut at any angle. A stainless line rubbing a wheel wears through."}, {"t": "torque", "label": "Banjo bolt / hard-line union", "nm": 15, "alt": [35], "c": {"level": "single", "n": 1, "note": "No factory figure found this pass. Kit sheets range from 15 Nm (union) to 35 Nm (banjo). Snug, then check for weeping under pressure."}}]}, {"n": 4, "title": "Repeat at every corner", "blocks": [{"t": "text", "b": "Same at the other three. Keep the reservoir from running dry."}]}, {"n": 90, "title": "Set up the pressure bleeder", "blocks": [{"t": "text", "b": "Turkey-baster the old fluid out of the reservoir down to the minimum line and refill with fresh DOT 4 from a sealed bottle. Screw the bleeder cap onto the reservoir and pump it to 10–15 psi. Keep the reservoir topped the whole time; if it runs dry the ABS unit takes in air and only a scan tool can bleed it."}, {"t": "warn", "b": "Brake fluid strips paint in minutes. Cover the fender and wing, keep a spray bottle of water handy, and wipe drips immediately."}]}, {"n": 91, "title": "Bleed in the manual's order", "caution": true, "blocks": [{"t": "text", "b": "Manual car first: 11mm on the clutch slave bleeder (on the bell housing), let 50 ml run, close, pump the clutch pedal 10–15 times, open again for another 50 ml, close. Then the brakes: front-left, front-right, rear-left, rear-right. Yes, front first; the ABS unit's layout makes the usual furthest-first rule wrong on this car. At each caliper: dust cap off, 11mm wrench on the nipple, hose into a catch bottle, open until the fluid runs clear and bubble-free, close, cap."}, {"t": "ill", "id": "bleed-order", "cap": "The order VW specifies. Clutch slave first on a manual."}, {"t": "note", "b": "Finishing touch owners swear by: after the pressure bleed, have a helper do five firm pedal strokes per caliper (open the nipple with the pedal down, close before it comes up) to chase any last air."}]}, {"n": 92, "title": "Close up and test", "blocks": [{"t": "text", "b": "Release bleeder pressure, remove the cap, set the reservoir level between the marks (not above MAX; the pads will wear and the level will rise as they're changed). Pedal should be firm within the first inch. Drive gently around the block, brake progressively harder, and check every bleeder for weeping."}]}], "alsoReplace": [{"name": "Pads and rotors", "why": "Same wheels-off session; see those guides."}, {"name": "Clutch line (manual)", "why": "Stainless clutch line is the same idea for a firmer clutch pedal and lives on the same reservoir."}], "check": {"tab": "Rubber or steel?", "title": "Is it worth it on a street car?", "illId": "bleed-order", "illCap": "The gain is consistency, not stopping distance.", "rows": [{"see": "Stock pads, daily driving", "means": "You'll notice a slightly firmer pedal, mostly at first.", "do": "Do it when the rubber hoses need replacing anyway."}, {"see": "Performance pads, spirited driving", "means": "Pedal feel under heat is where stainless shows.", "do": "Yes, with a full flush and good fluid."}, {"see": "Track days", "means": "Consistency lap to lap.", "do": "Yes, with TYP200 or RBF600."}], "c": {"level": "community", "n": 3, "note": "Forum consensus."}}, "aftercare": ["Check every fitting for weeping after the first hard stops.", "Re-check routing after a week: nothing should show rub marks."], "disagreements": [{"topic": "Fitting torque", "pos": "No factory value found; kits vary.", "call": "Snug and leak-check. Flagged single-source."}, {"topic": "Worth it on a stock car?", "pos": "Forum split.", "call": "When the rubber hoses are due anyway, yes."}], "sources": ["Brake bleeding sources (see flush guide)", "StopTech / Goodridge / ECS product listings", "Forum threads on hose ageing and routing"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('dsg',$j${"id": "dsg", "title": "DSG fluid & filter service", "fits": "2006 VW GTI · 2.0T FSI · 6-speed DSG (02E / DQ250)", "heroId": "dsg-hero", "alsoFits": "Every 6-speed wet-clutch DSG (02E/0D9) 2005–2019: Golf, GTI, Jetta, Eos, Passat, A3, TT", "category": "Drivetrain", "kind": "repair", "glance": {"timeFirst": "1.5–2 hr", "timeRepeat": "1 hr", "difficulty": 2.5, "cost": "$120–180", "risk": "Fluid level is set by temperature; get it wrong and the box shifts badly", "why": "The DSG's wet clutches and mechatronic unit live in this oil. It shears and fills with clutch material, and VW's 40,000-mile interval is not a suggestion: neglected fluid is behind most of the harsh-shift and mechatronic stories. This service is cheap and very doable at home.", "note": "An afternoon. The only fiddly part is setting the level at the right temperature."}, "heroCap": "Drain plug and overflow tube underneath; filter under a cap on top. The level is set by letting excess run out of the overflow tube with the engine running and the fluid at 35–45°C.", "lifespan": {"title": "When to expect it", "headline": ["Every 40,000 miles, per the factory schedule"], "earliest": "Sooner (30k) if tuned, towing, or tracked", "detail": "Owners who go long describe shudder on take-off, clunky low-speed shifts and hesitation in reverse. Fresh fluid often clears mild versions of these; it won't fix a worn mechatronic unit, but it's the first thing to do.", "factors": ["Tune (more torque through the clutches)", "Stop-and-go city driving", "Unknown history on a used car"], "inspect": ["Nothing to inspect between services; just do it on time"], "confidence": {"level": "high", "n": 4, "note": "Factory interval confirmed by three vendor sources; symptoms are forum consensus."}}, "should": {"yesIf": ["40,000 miles since the last service, or unknown", "Shudder on take-off, harsh or lazy low-speed shifts", "You just bought the car", "You've tuned it"], "codes": [], "notes": ["Fluid spec is VW TL 521 82 (G 052 182 A2). Nothing else. The dual clutches run in this oil and the friction spec matters.", "Filter part is 02E 305 051 C; the cap o-ring comes with a good kit."], "confidence": {"level": "high", "n": 4, "note": "Spec, capacity and interval agree across all sources."}}, "parts": [{"tier": "oe", "name": "DSG fluid, 6 × 1 L", "pn": "G 052 182 A2", "note": "Service fill is 5.2 L; buy six so the level-set doesn't run short", "price": "$90–120", "links": []}, {"tier": "oe", "name": "DSG filter with o-ring", "pn": "02E 305 051 C", "note": "", "price": "$30–45", "links": []}, {"tier": "oe", "name": "Drain plug crush washer", "pn": "in most kits", "note": "", "price": "$3", "links": []}], "aftermarket": [{"name": "Ravenol DCT/DSG, Eurol DCF 1404, Pentosin FFL-2", "note": "Third-party fluids that meet TL 521 82. Fine; the OE fluid is also made by a third party.", "price": "$15–20 / L", "signal": "Meets spec", "links": []}, {"name": "Blauparts / FCP Euro service kits", "note": "Fluid, filter, washer and the fill adapter in one box.", "price": "$130–180", "signal": "One-box pick", "links": [{"store": "FCP Euro DIY", "url": "https://www.fcpeuro.com/blog/vw/audi-dsg-automatic-transmission-service-diy"}]}], "tools": [{"name": "14mm hex bit (drain plug), 8mm hex bit (overflow tube), 24mm socket or filter socket (filter cap)"}, {"name": "DSG fill adapter (VAS 6262-style) with hose and pump, or a fluid transfer pump into the drain hole"}, {"name": "VCDS or a scan tool that reads transmission fluid temperature; an infrared thermometer as a fallback"}, {"name": "Drain pan ≥ 6 L, torque wrench to 45 Nm, ramps or four stands: the car must be level"}], "before": ["The car must be level for the level-set. Four stands or ramps at both ends.", "Fluid should be warm but not hot when you drain: a short drive, then let it sit 10 minutes.", "Read the level-set step twice before you start. It's the whole job."], "steps": [{"n": 1, "title": "Level, warm, belly pan off", "blocks": [{"t": "text", "b": "Car level on stands, belly pan off. Drain pan under the transmission's bottom plug."}]}, {"n": 2, "title": "Drain", "blocks": [{"t": "text", "b": "14mm hex: remove the drain plug. Fluid runs. When it slows, 8mm hex into the overflow tube inside the drain hole and unscrew it: another litre or so drops. Expect about 5 litres total; measure it roughly so you know what to put back."}, {"t": "ill", "id": "dsg-hero", "cap": "Plug, then the tube inside it. The tube's height is what sets the level later."}]}, {"n": 3, "title": "Filter", "blocks": [{"t": "text", "b": "Top of the transmission, under the airbox/battery area: the round filter cap. 24mm socket, unscrew, lift out the filter (fluid will follow; rag ready). New o-ring on the cap, new filter in, cap on."}, {"t": "torque", "label": "Filter cap", "nm": 20, "c": {"level": "medium", "n": 2, "note": "20 Nm (15 lb-ft) from two owner guides. Plastic cap: snug."}}]}, {"n": 4, "title": "Overflow tube back, fill", "blocks": [{"t": "text", "b": "Overflow tube back in (3 Nm, barely more than finger tight). Thread the fill adapter into the drain hole and pump in about 5 litres, shaking each bottle first. Leave the adapter on."}, {"t": "torque", "label": "Overflow tube (8mm hex)", "nm": 3, "c": {"level": "single", "n": 1, "note": "From the Mk5 FAQ procedure. Plastic; snug."}}]}, {"n": 5, "title": "Set the level", "caution": true, "blocks": [{"t": "text", "b": "Start the engine with the adapter connected and the pan underneath. Foot on the brake, move the lever through P–R–N–D–S, holding each about 3 seconds, back to P. Watch the fluid temperature on VCDS (Auto Trans, measuring block 19) or an IR gun on the pan. Between 35 and 45°C, open the adapter's valve (or remove the adapter and let the drain hole weep). Excess fluid runs out of the overflow tube: expect half a litre to three-quarters. When it slows to a drip, remove the adapter and fit the plug with a new washer."}, {"t": "warn", "b": "Do not let it go past 45°C with the plug out, and do not switch the engine off with the plug out. Hot fluid has expanded and the level will be set low; a stopped engine dumps the fluid held in the box. If more than a litre runs out, stop and reassess: something's wrong with the fill."}, {"t": "torque", "label": "Drain plug (14mm hex)", "nm": 45, "c": {"level": "high", "n": 3, "note": "45 Nm across FCP Euro, the Mk5 FAQ and Blauparts."}}]}, {"n": 6, "title": "Adaptation and test drive", "blocks": [{"t": "text", "b": "Engine off, belly pan on. Many owners run the DSG basic-settings adaptation in VCDS after a service; it's optional but helps if shifts were harsh. Drive it. Check around the filter cap and plug for leaks when you get back."}]}], "alsoReplace": [{"name": "Engine air filter", "why": "The airbox is in your way for the filter cap anyway."}, {"name": "Haldex/other fluids", "why": "Not on a GTI. On an R32 or Golf R the Haldex service shares the afternoon."}], "check": {"tab": "Read the fluid", "title": "What came out?", "illId": "dsg-hero", "illCap": "Fresh DSG fluid is pale amber and thin.", "rows": [{"see": "Amber, clean, smells like oil", "means": "On schedule.", "do": "Normal service."}, {"see": "Dark brown, opaque, burnt smell", "means": "Long overdue; clutch material in suspension.", "do": "Service now; consider a second change after 5–10k to dilute what's left."}, {"see": "Metal glitter or chunks on the magnet", "means": "Mechanical wear, not just old fluid.", "do": "Service, then a transmission specialist. Fluid won't fix this."}], "c": {"level": "community", "n": 3, "note": "Forum consensus."}}, "aftercare": ["Re-check the plug and filter cap for leaks after a day.", "Shifts may feel different for a few drives while the mechatronics adapt.", "Note the mileage; next in 40k."], "disagreements": [{"topic": "How to read the temperature", "pos": "VCDS measuring block vs an IR gun on the pan.", "call": "VCDS if you have it; the IR gun works on the pan and is what two vendor guides use."}, {"topic": "How much fluid", "pos": "5.2 L (spec) vs 5.5 L (FAQ fill).", "call": "Buy six litres; the overflow sets the level."}, {"topic": "Drain plug bit", "pos": "14mm hex (four sources) vs 14mm triple-square (one).", "call": "Hex."}], "sources": ["FCP Euro DSG service DIY (02E)", "Blauparts DSG articles (capacity, spec, interval)", "VWVortex 'DSG Fluid and Filter Technical Write-Up' / Mk5 FAQ", "Pelican Parts Mk5 GTI DSG article", "Golfmk7 DSG DIY and UroTuning guide (torques)"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
insert into guides (id,content) values ('clutch',$j${"id": "clutch", "title": "Clutch replacement", "fits": "2006 VW GTI · 2.0T FSI · 6-speed manual (02Q)", "heroId": "clutch-hero", "alsoFits": "Mk5/Mk6 GTI, Jetta, A3 with the 02Q 6-speed; TSI cars identical at the transmission", "category": "Drivetrain", "kind": "repair", "variants": {"question": "What's going back in?", "hint": "A factory-style kit keeps the dual-mass flywheel (quiet, softer pedal). A single-mass or stage kit is for tuned cars: lighter, more clamp, some chatter at idle.", "options": [{"id": "oe", "label": "OE-style (dual-mass flywheel)", "when": "Stock or Stage 1. Sachs, LuK. Replace the flywheel if it's worn."}, {"id": "stage", "label": "Aftermarket single-mass / stage kit", "when": "Stage 2+, K04. Southbend, Sachs Performance, Clutchmasters. Heavier pedal, idle chatter is normal."}]}, "glance": {"timeFirst": "10–16 hr (two days)", "timeRepeat": "6–8 hr", "difficulty": 5, "cost": "$600–1,500 parts", "risk": "Transmission on a jack · engine on a support bar · torque-to-yield bolts everywhere", "why": "The clutch is the one friction part in the drivetrain. When it slips, the pedal gets high, or the release bearing screams, the transmission has to come out to fix it. That's why this is the hardest job in the app, and why you replace everything you can reach while it's out.", "note": "One owner claims three hours. The manufacturer guide says plan two full days. Believe the manufacturer."}, "heroCap": "Flywheel bolts to the crank, clutch disc sandwiched between it and the pressure plate, release bearing and slave cylinder on the transmission nose. The whole gearbox has to come out to reach any of it.", "lifespan": {"title": "When to expect it", "headline": [{"text": "Factory clutch: typically 100,000–150,000 miles on a stock car", "only": ["oe"]}, {"text": "Stock clutch on a Stage 2 tune: often 40,000–80,000 miles before it slips", "only": ["stage"]}], "earliest": "Much sooner with a tune and a heavy right foot, or a leaking rear main seal soaking the disc", "detail": "Symptoms in order: pedal engagement point creeping toward the top, slipping in high gears under boost, a whir or squeal with the pedal down (release bearing), then judder. The dual-mass flywheel usually fails around the same time on high-mileage cars: rattle at idle that goes away with the pedal down.", "factors": ["Stage 2+ tune", "Launches", "Rear main seal or input shaft seal leak", "City driving"], "inspect": ["Nothing to inspect from outside; watch the engagement point"], "confidence": {"level": "community", "n": 5, "note": "Owner reports across several forums; no factory interval."}}, "should": {"yesIf": ["Slipping: revs climb without speed, especially 4th–6th under boost", "Engagement point at the very top of the pedal travel", "Squeal or whir with the pedal pressed", "Rattle at idle that stops with the clutch in (dual-mass flywheel)", "You're going Stage 2 and the clutch is original"], "codes": [], "notes": ["Hydraulics first: a soft or sinking pedal is often the slave or master cylinder, not the clutch. Bleed it and rule that out before you pull a transmission.", {"text": "Single-mass flywheels chatter at idle and in neutral. It's the sound of gear lash without the dual-mass damper. Owners who don't know this take their cars back to the shop. It's normal.", "only": ["stage"]}, {"text": "If the dual-mass flywheel rocks more than a few millimetres by hand or has any radial play, it's done. Reusing a tired one under a new clutch is the classic false economy.", "only": ["oe"]}], "confidence": {"level": "high", "n": 4, "note": "Symptoms and procedure consistent across the manufacturer guide and three owner DIYs."}}, "parts": [{"tier": "oe", "name": "Clutch kit: disc, pressure plate, release bearing/slave", "pn": "Sachs or LuK for the 02Q", "note": "", "price": "$300–450", "links": [], "only": ["oe"]}, {"tier": "oe", "name": "Dual-mass flywheel", "pn": "LuK", "note": "If the old one has play or heat spots", "price": "$400–600", "links": [], "only": ["oe"]}, {"tier": "aftermarket", "name": "Stage clutch kit with single-mass flywheel", "pn": "see options below", "note": "Includes flywheel bolts, pressure plate bolts, alignment tool, slave", "price": "$900–1,500", "links": [], "only": ["stage"]}, {"tier": "oe", "name": "Flywheel bolts (×8) and pressure plate bolts (×6)", "pn": "torque-to-yield", "note": "New, always. Most kits include them", "price": "$25", "links": []}, {"tier": "oe", "name": "Concentric slave cylinder / release bearing", "pn": "02Q 141 671", "note": "Never reuse. In most kits", "price": "$60–90", "links": []}, {"tier": "oe", "name": "Rear main seal", "pn": "06D 103 171", "note": "Now or never", "price": "$25", "links": []}, {"tier": "oe", "name": "Transmission input shaft seal, axle flange seals", "pn": "—", "note": "Cheap, and you're there", "price": "$30", "links": []}, {"tier": "oe", "name": "DOT 4 fluid for the clutch bleed", "pn": "—", "note": "", "price": "$10", "links": []}], "aftermarket": [{"name": "Southbend Stage 2 Daily / Stage 3", "note": "The forum default for tuned FSIs. Stage 2 Daily holds Stage 2 power with a near-stock pedal; Stage 3 for K04 and up, heavier pedal.", "price": "$1,000–1,400", "signal": "Forum favorite", "links": []}, {"name": "Sachs Performance", "note": "OE maker's uprated kit; organic disc, more clamp, pairs with the stock dual-mass or their SMF.", "price": "$700–1,000", "signal": "Quiet upgrade", "links": []}, {"name": "Clutchmasters FX series", "note": "Wide range of disc materials; check the pedal effort rating before buying anything above FX300 for a daily.", "price": "$800–1,300", "signal": "Pick by pedal weight", "links": []}, {"name": "ECS lightweight flywheel kit", "note": "Chromoly SMF with clutch, slave and hardware. The install PDF is the reference for this guide.", "price": "$900–1,100", "signal": "Best documented", "links": [{"store": "ECS install PDF", "url": "http://bd8ba3c866c8cbc330ab-7b26c6f3e01bf511d4da3315c66902d6.r6.cf1.rackcdn.com/PDF_13689_Volkswagen_MKV_MKVI_TSI_Lightweight_Flywheel_Installation_R3.pdf"}]}], "tools": [{"name": "Engine support bar and a transmission jack. Not optional."}, {"name": "Sockets 10, 13, 16, 18, 22, 24mm (12-point) · M10 and M12 triple-square · 9mm 12-point for pressure-plate bolts (kit-dependent) · 6mm hex"}, {"name": "Torque wrenches: ¼\" for 12 Nm, ½\" for 80–200 Nm; angle gauge or paint pen for the +90° bolts"}, {"name": "Clutch alignment tool (in kit), flywheel lock or two old bolts and a pry bar, brake-fluid catch bottle, connector release tool"}, {"name": "A printed bolt template taped to a box: the bell-housing bolts are all different lengths"}], "before": ["Read the manufacturer PDF end to end first. This guide is the map; the PDF has the photos.", "Two days, a helper for the transmission, and a clean floor to lay parts out in order.", "Every bolt with a '+90°' is torque-to-yield and is replaced.", "Disconnect the battery negative first. It's coming out anyway.", "Bench-bleed the new slave in a jug of fluid before it goes on the transmission."], "steps": [{"n": 1, "title": "Top side: airbox, battery, tray", "blocks": [{"t": "text", "b": "Engine cover/airbox out (see the air filter guide), scoop off (T25). Battery cover, negative then positive terminals (10mm), hold-down (13mm), battery out, both halves of the box, then the three 10mm tray bolts and the tray. You now see the top of the transmission."}]}, {"n": 2, "title": "Shifter cables, clutch line, electrics", "blocks": [{"t": "text", "b": "Unclip both shift cable ends from the selector and relay levers (retaining clip, then a gentle pry) and unbolt the cable bracket (two 13mm bolts and a nut); wire it up out of the way. Pull the clips and pop the clutch line out of the bleeder block into a catch bottle, then the block off the slave inlet. Ground strap off the mount bracket (13mm). Unplug the reverse switch and the starter solenoid, starter cable nut (13mm) off."}, {"t": "warn", "b": "Brake fluid from the clutch line goes everywhere. Catch it, and don't pinch the plastic hard line."}]}, {"n": 3, "title": "Upper bolts and the driver's axle", "blocks": [{"t": "text", "b": "Upper starter bolt and both upper bell-housing bolts (18mm). Left front wheel off; six inner CV bolts (M10 triple-square) with a helper holding the brake; outer CV bolt (24mm 12-point) with the wheel off the ground. Fender liner and the cooling duct out. Lower starter bolt, harness bracket, starter out."}]}, {"n": 4, "title": "Underneath: charge pipes, shields, right axle, pendulum", "blocks": [{"t": "text", "b": "Belly pan off. Driver's-side charge hose off (clamp and clip), MAP sensor unplugged, charge duct's two T30 screws out and the duct wiggled out between engine and fans; passenger charge hose off. Right CV heat shield (two 17mm). Six right inner CV bolts, tie the shaft up. Three left ball-joint nuts (16mm), pull the arm down, and the left axle comes out. Two downpipe-bracket bolts (13mm)."}]}, {"n": 5, "title": "Support the engine, drop the mounts", "caution": true, "blocks": [{"t": "text", "b": "Engine support bar across the fenders, hook on the head's lift bracket, tension until the engine just lifts. Three pendulum bolts (16/22mm), slide the mount out. Oil level sensor unplugged if fitted. Three transmission mount bolts (18mm). Lower the engine about two inches on the bar and remove the three bracket bolts and the bracket. Relay lever off (clip, slide out); selector shaft nut (13mm) and lever off, gently, no hammering."}, {"t": "warn", "b": "From here the engine hangs on the bar and the transmission on its last bolts. Check the bar's feet and chain before every step. Nobody under the transmission."}]}, {"n": 6, "title": "Transmission out", "caution": true, "blocks": [{"t": "text", "b": "Rear bell-housing bolt (18mm). Transmission jack under the box, strapped. Front bolt and the two lower bolts (16mm). With your helper: pull it back off the block, rotate the diff end up, angle the nose forward and walk the right CV flange around the flywheel, adjusting the engine bar and jack for clearance. Once clear, lower it and move it to the bench."}, {"t": "ill", "id": "clutch-hero", "cap": "What you're looking at once it's out: flywheel and pressure plate on the engine, release bearing/slave on the transmission nose."}, {"t": "note", "b": "Owner alternative: unbolt the inner CV flanges from the transmission (6mm hex) instead of pulling the whole left axle, and pull the front intercooler pipe for more room. Same result."}]}, {"n": 7, "title": "Old clutch and flywheel off", "blocks": [{"t": "text", "b": "Loosen all six pressure-plate bolts, then remove them alternately with a hand on the plate; it comes off its three dowels with the disc, sometimes with a pry. Eight flywheel bolts (M12 triple-square): impact, or two old plate bolts and a pry bar to lock it. Firm grip on the last bolt; the dual-mass is heavy."}]}, {"n": 8, "title": "Clean up and the seal you came for", "blocks": [{"t": "text", "b": "Clean the crank flange, block face and separator plate. Look at the rear main seal: any wetness, replace it now (pry out, tap the new one square). Both alignment dowels in the block; the separator plate hooked behind the seal plate and resting on the dowels."}]}, {"n": 9, "title": "Flywheel and clutch on", "caution": true, "blocks": [{"t": "text", "b": "Flywheel onto the crank (offset holes, one position). New bolts, pre-coated with locker. Torque in the star sequence in three stages, marking each bolt with paint after the angle stage.", "only": ["oe", "stage"]}, {"t": "torque", "label": "Flywheel bolts (×8, NEW)", "nm": 60, "c": {"level": "high", "n": 3, "note": "Stage 1: 30 Nm, stage 2: 60 Nm, stage 3: +90°. Manufacturer PDF; owner DIYs consistent."}, "note": "30 → 60 → +90°"}, {"t": "text", "b": "Wipe the flywheel face and the new pressure plate with brake cleaner. Test the disc on the transmission's input-shaft splines first. Disc against the flywheel, 'transmission side' facing you, alignment tool through it into the crank. Pressure plate over the dowels, six new bolts evenly and alternately."}, {"t": "torque", "label": "Pressure plate bolts (×6, NEW)", "nm": 20, "alt": [22], "c": {"level": "varies", "n": 2, "note": "20 Nm for the aftermarket SMF kit's 9mm 12-point bolts; 22 Nm for the factory dual-mass plate bolts. Follow your kit's sheet."}}, {"t": "warn", "b": "No grease, no fingerprints on the friction faces. One oily thumbprint on the disc is a juddering clutch for its whole life."}]}, {"n": 10, "title": "Slave, splines, and back in", "caution": true, "blocks": [{"t": "text", "b": "Three 9mm bolts and the old slave/release bearing comes off the bell housing. Clean the housing and splines; check the input shaft seal. New (bench-bled) slave on with new bolts (12 Nm metal / 15 Nm plastic). Thin, even film of the kit's spline lube on the input shaft. Transmission back on the jack, up, and walked home against the block until it seats flat. Start the two lower bolts, front, rear, then the uppers, none tight, and check nothing's pinched."}, {"t": "note", "b": "Reconnect the clutch line before the box is pushed fully home: the pressure-plate fingers push the slave and it will spray fluid otherwise."}, {"t": "torque", "label": "Bell-housing bolts, upper M12 and rear M12", "nm": 80, "c": {"level": "high", "n": 3, "note": "80 Nm (manufacturer, owner DIYs)"}}, {"t": "torque", "label": "Bell-housing bolts, lower M10 and front M10", "nm": 40, "alt": [45], "c": {"level": "varies", "n": 2, "note": "40 Nm (manufacturer) vs 45 Nm (owner DIY). Either is fine; the base sizes match."}}]}, {"n": 11, "title": "Mounts, pendulum, axles, starter", "blocks": [{"t": "text", "b": "Selector lever and nut (20 Nm), relay lever and clip. Bracket back (60 Nm + 90°, new bolts), raise the transmission, three mount bolts (60 Nm + 90°, new). Pendulum in: transmission bolts 50 Nm + 90°, subframe bolt 100 Nm + 90°. Engine bar off. Downpipe bracket. Left axle in, ball joint nuts (60 Nm cast arm / 100 Nm aluminium). Inner CV bolts both sides (70 Nm for M10). Starter (80 Nm), cable, solenoid, reverse switch, ground. Charge pipes and MAP. Shields, liner, wheel (120 Nm), outer CV bolt per its type."}, {"t": "torque", "label": "Transmission mount & bracket bolts (NEW)", "nm": 60, "c": {"level": "high", "n": 2, "note": "60 Nm + 90° (manufacturer; owner DIY: 50 Nm + 90° on the older 02M)."}, "note": "+90° turn"}]}, {"n": 12, "title": "Cables, bleed, battery, test", "blocks": [{"t": "text", "b": "Bleeder block and clutch line, shifter cable bracket and cables. Battery tray, battery. Bleed the clutch: pressure bleeder on the reservoir, 11mm on the slave nipple, run fluid until clear, pump the pedal, repeat. Airbox on. Start it in neutral, clutch in, feel for a normal pedal. First drive: gentle, all gears, listen."}]}, {"n": 13, "title": "Break it in", "blocks": [{"t": "text", "b": "New friction surfaces need heat cycles. 500 miles of normal driving, no launches, no boost in low gears with the pedal slipping, before you lean on it.", "only": ["oe"]}, {"t": "text", "b": "Stage kits are stricter: most makers want 500–1,000 miles of city driving, no hard launches, no boosted slip, or the disc glazes and the warranty is void. The idle chatter you hear is the single-mass flywheel. It's normal.", "only": ["stage"]}]}], "alsoReplace": [{"name": "Rear main seal", "why": "It's staring at you with the flywheel off. If it leaks later, the whole job repeats."}, {"name": "Concentric slave cylinder / release bearing", "why": "Never reuse it. Most kits include one; if yours didn't, buy one."}, {"name": "Transmission input shaft seal and axle flange seals", "why": "Cheap, accessible with the box out, and a leaking flange seal drips onto the new clutch's neighbourhood."}, {"name": "Pendulum (dogbone) mount and transmission mount", "why": "Both are unbolted. Tired mounts are the usual source of driveline clunk, and stage clutches punish soft mounts."}, {"name": "Clutch bleeder block and line", "why": "The factory plastic block restricts flow; a high-flow block improves pedal feel and is $40 while you're bleeding anyway."}, {"name": "Starter", "why": "It's in your hand. On a 150k car, check the pinion and the solenoid contacts; a new starter is a lot cheaper than pulling the box again for one."}], "check": {"tab": "OE or stage?", "title": "Which clutch belongs in your car?", "illId": "clutch-hero", "illCap": "Dual-mass damps the driveline; single-mass revs faster and chatters.", "rows": [{"see": "Stock or Stage 1, daily driver", "means": "The factory setup is quiet, light and lasts.", "do": "OE-style kit; new dual-mass if the old one has play."}, {"see": "Stage 2 / K04, daily driver", "means": "Stock clutch will slip; you want clamp without a leg workout.", "do": "Southbend Stage 2 Daily or Sachs Performance with the stock-style flywheel."}, {"see": "Big turbo or track", "means": "Holding power first.", "do": "Stage 3+ with single-mass. Accept the pedal and the chatter."}], "c": {"level": "community", "n": 4, "note": "Forum consensus; vendor tiers."}}, "aftercare": ["Break in as above.", "Re-torque nothing; the TTY bolts are done. Do re-check the pendulum and mount bolts didn't get missed.", "Clutch pedal soft after a week: air in the line; bleed again."], "disagreements": [{"topic": "How long?", "pos": "'About 3 hours' (one owner) vs 'plan two full days' (manufacturer).", "call": "Two days for a first time. The owner had done it before and skipped nothing."}, {"topic": "Pressure plate torque", "pos": "20 Nm (SMF kit) vs 22 Nm (OE dual-mass).", "call": "Follow the kit's sheet; both shown."}, {"topic": "Pull the axle or just the flanges?", "pos": "Manufacturer pulls the left axle; an owner unbolts both inner flanges instead.", "call": "Either works. Flanges is quicker; axle gives more room."}, {"topic": "Is the idle chatter a fault?", "pos": "New SMF owners think so.", "call": "No. It's the design."}], "sources": ["ECS Tuning Mk5/Mk6 02Q lightweight flywheel & clutch installation PDF (57 pages)", "VWVortex 'Transmission Removal Clutch Replacement diy Quick Version' (2008)", "Golfmk6 '6 Speed Manual Clutch Replacement DIY' (2014)", "Pelican Parts Mk4 clutch article (technique)", "NGP, Southbend, Sachs listings"], "embeds": []}$j$::jsonb) on conflict (id) do update set content=excluded.content, updated_at=now();
